/* Color schemes */
/*
Umbra
Chalk on wet asphalt

Palette tokens are kept separate from their semantic assignments so that
components can depend on the shared Minimal/Obsidian interface below.
*/
:root {
  --umbra-base: #0a0d10;
  --umbra-surface: #0f1418;
  --umbra-border: #141a20;
  --umbra-crimson: #b36c70;
  --umbra-cream: #d4c8a8;
  --umbra-sage: #8aa890;
  --umbra-butter: #a89868;
  --umbra-ochre: #b89968;
  --umbra-lavender: #a896c0;
  --umbra-dust: #88a4b8;
}

.theme-dark {
  /* Umbra palette interface */
  --base-h: 210;
  --base-s: 23%;
  --base-l: 5%;
  --accent-h: 357;
  --accent-s: 28%;
  --accent-l: 56%;
  --bg1: var(--umbra-base);
  --bg2: var(--umbra-surface);
  --bg3: rgba(212, 200, 168, 0.06);
  --ui1: var(--umbra-border);
  --ui2: #202830;
  --ui3: #303a43;
  --tx1: var(--umbra-cream);
  --tx2: #9a907a;
  --tx3: #6e6758;
  --tx4: #b8ad91;
  --ax1: var(--umbra-crimson);
  --ax2: #c87c80;
  --ax3: #9f5d61;
  --hl1: rgba(179, 108, 112, 0.25);
  --hl2: rgba(184, 153, 104, 0.28);
  --sp1: var(--umbra-base);
  /* Status and palette colors */
  --color-red-rgb: 179, 108, 112;
  --color-orange-rgb: 168, 152, 104;
  --color-yellow-rgb: 184, 153, 104;
  --color-green-rgb: 138, 168, 144;
  --color-cyan-rgb: 136, 164, 184;
  --color-blue-rgb: 136, 164, 184;
  --color-purple-rgb: 168, 150, 192;
  --color-pink-rgb: 200, 138, 142;
  --color-red: var(--umbra-crimson);
  --color-orange: var(--umbra-butter);
  --color-yellow: var(--umbra-ochre);
  --color-green: var(--umbra-sage);
  --color-cyan: var(--umbra-dust);
  --color-blue: var(--umbra-dust);
  --color-purple: var(--umbra-lavender);
  --color-pink: #c88a8e;
  --background-modifier-error: #8a4f53;
  --background-modifier-error-hover: #9a5f63;
  --background-modifier-success: #5a7a4c;
  --text-error: #c87579;
  --text-success: var(--umbra-sage);
  /* Editor and syntax highlighting */
  --code-background: var(--umbra-surface);
  --code-block-background: var(--umbra-surface);
  --code-normal: var(--umbra-cream);
  --code-comment: #6e6758;
