  --code-important: #c88a8e;
  --code-keyword: var(--umbra-lavender);
  --code-operator: var(--umbra-ochre);
  --code-property: var(--umbra-dust);
  --code-punctuation: #9a907a;
  --code-string: var(--umbra-sage);
  --code-tag: #c88a8e;
  --code-value: var(--umbra-ochre);
  --code-variable: var(--umbra-dust);
  --cursor-color: var(--umbra-crimson);
  --cursor-width: 4px;
}

